        tp_set.add(name);
        if (!NodeUtil.isTypeParam(sp)) continue;
        typeParams.add(name);
        List<FType> bs = new ArrayList<FType>();
        bounds.put(name, bs);
        for (Type tr : sp.getExtendsClause()) {
            try {
                FType tt = et.evalType(tr);
                abm.meetPut(name, tt);
