public static boolean argsMatchTypes(List<FValue> args, List<FType> l) {
    for (int j = 0; j < args.size(); j++) {
        FValue a = args.get(j);
        FType t = Useful.clampedGet(l, j).deRest();
        try {
            if (!t.typeMatch(a)) {
                return false;
            }
        }
        catch (FortressException e) {
            return false;
        }
    }
    return true;
}

